// Resuming a run without repeating steps (DESIGN.md §"Data model": "`events` is an append-only step log.
// Every step is idempotent, and runs resume from here.").
//
// A crashed run leaves its finished steps logged as `done`, and the step it was in the middle of as `started`
// with nothing after it. nextSteps() reads that log and answers the only question a resumed run asks: which
// steps still have to run, and in what order. A step that is `done` is never returned, so a resumed run never
// repeats finished work. A step that failed is returned again, but after MAX_FAILURES it has given up: it is
// left out, and so is everything downstream, because a dependent can never see its dependency done.

/** One step of a plan. `key` is unique within the plan; every key in `dependsOn` must be `done` before it runs. */
export interface Step {
  key: string;
  dependsOn: string[];
}

/** One append-only log entry. A step can appear several times: a `started` per attempt, then `done` or `failed`. */
export interface StepEvent {
  key: string;
  status: "started" | "done" | "failed";
}

/** Failures after which a step is given up on: three attempts in total (the first run plus two retries). */
export const MAX_FAILURES = 3;

/**
 * The keys that still have to run, in plan order: every dependency is `done`, the step is not `done` itself,
 * and it has not failed MAX_FAILURES times. A step that only `started` is returned again, as is one that
 * failed fewer than MAX_FAILURES times. Steps given up on — and everything that depends on them, directly or
 * through another given-up step — are left out.
 */
export function nextSteps(plan: { steps: Step[] }, events: StepEvent[]): string[] {
  const done = new Set<string>();
  const failures = new Map<string, number>();
  for (const e of events) {
    if (e.status === "done") done.add(e.key);
    else if (e.status === "failed") failures.set(e.key, (failures.get(e.key) ?? 0) + 1);
  }

  // A step that eventually finished is done, not given up on, however it got there.
  const givenUp = (key: string) => !done.has(key) && (failures.get(key) ?? 0) >= MAX_FAILURES;

  return plan.steps
    .filter((step) => !done.has(step.key) && !givenUp(step.key) && step.dependsOn.every((dep) => done.has(dep)))
    .map((step) => step.key);
}

// F23: resume a run without repeating steps. nextSteps() reads the append-only events log and returns the
// keys that still have to run, in plan order.
import { describe, expect, test } from "bun:test";
import { MAX_FAILURES, nextSteps, type Step, type StepEvent } from "../src/agent/resume.ts";

const step = (key: string, ...dependsOn: string[]): Step => ({ key, dependsOn });
const ev = (key: string, status: StepEvent["status"]): StepEvent => ({ key, status });

/** A tiny three-step pipeline: a → b → c. */
const pipeline: Step[] = [step("a"), step("b", "a"), step("c", "b")];

describe("nextSteps", () => {
  test("a fresh run starts with the steps whose dependencies are all done", () => {
    expect(nextSteps({ steps: pipeline }, [])).toEqual(["a"]);
  });

  test("independent steps all run, in plan order", () => {
    const plan = [step("c"), step("a"), step("b")];
    expect(nextSteps({ steps: plan }, [])).toEqual(["c", "a", "b"]);
  });

  test("an empty plan has nothing to run", () => {
    expect(nextSteps({ steps: [] }, [])).toEqual([]);
  });

  test("continues from the next unfinished step after a crash", () => {
    const events = [ev("a", "started"), ev("a", "done"), ev("b", "started")];
    expect(nextSteps({ steps: pipeline }, events)).toEqual(["b"]);
  });

  test("a step that started but did not finish is returned again", () => {
    expect(nextSteps({ steps: pipeline }, [ev("a", "started")])).toEqual(["a"]);
  });

  test("never returns a finished step", () => {
    const events = [ev("a", "started"), ev("a", "done"), ev("b", "started"), ev("b", "done"), ev("c", "started"), ev("c", "done")];
    expect(nextSteps({ steps: pipeline }, events)).toEqual([]);
  });

  test("a finished step unblocks its dependents", () => {
    expect(nextSteps({ steps: pipeline }, [ev("a", "done")])).toEqual(["b"]);
    expect(nextSteps({ steps: pipeline }, [ev("a", "done"), ev("b", "done")])).toEqual(["c"]);
  });

  test("a dependent is not returned before its dependency is done", () => {
    const events = [ev("b", "started"), ev("b", "done")];
    expect(nextSteps({ steps: pipeline }, events)).toEqual(["a"]);
  });

  test("a failed step is returned again", () => {
    expect(nextSteps({ steps: pipeline }, [ev("a", "started"), ev("a", "failed")])).toEqual(["a"]);
  });

  test("a step that failed twice is still returned again", () => {
    const events = [ev("a", "started"), ev("a", "failed"), ev("a", "started"), ev("a", "failed")];
    expect(nextSteps({ steps: pipeline }, events)).toEqual(["a"]);
  });

  test(`a step that failed ${MAX_FAILURES} times is excluded`, () => {
    const events = [ev("a", "started"), ev("a", "failed"), ev("a", "started"), ev("a", "failed"), ev("a", "started"), ev("a", "failed")];
    expect(nextSteps({ steps: pipeline }, events)).toEqual([]);
  });

  test("the dependents of an excluded step are not returned", () => {
    const events = [
      ev("a", "failed"), ev("a", "failed"), ev("a", "failed"),
      ev("b", "started"),
      ev("x", "done"),
    ];
    const plan = [step("a"), step("b", "a"), step("c", "b"), step("x", "b")];
    // b depends on the given-up a; c and x are downstream of b, so they are left out too.
    expect(nextSteps({ steps: plan }, events)).toEqual([]);
  });

  test("an excluded step does not block unrelated work", () => {
    const plan = [step("a"), step("b", "a"), step("x")];
    const events = [ev("a", "failed"), ev("a", "failed"), ev("a", "failed")];
    expect(nextSteps({ steps: plan }, events)).toEqual(["x"]);
  });

  test("a step that failed a few times and then finished is done, not excluded", () => {
    const plan = [step("a"), step("b", "a")];
    const events = [ev("a", "failed"), ev("a", "failed"), ev("a", "failed"), ev("a", "done")];
    expect(nextSteps({ steps: plan }, events)).toEqual(["b"]);
  });

  test("events for keys that are not in the plan are ignored", () => {
    expect(nextSteps({ steps: [step("a")] }, [ev("nope", "done"), ev("nope", "failed")])).toEqual(["a"]);
  });

  test("a dependency that the plan never mentions is never done, so the step waits", () => {
    expect(nextSteps({ steps: [step("a", "missing")] }, [])).toEqual([]);
  });
});

